ssize_t get_acl_uncached(struct inode *inode, void *buf, size_t buflen) {
    struct page **pages;
    int num_pages = (buflen + PAGE_SIZE - 1) / PAGE_SIZE;
    ssize_t ret;
    int i;

    pages = kmalloc_array(num_pages, sizeof(struct page *), GFP_KERNEL);
    if (!pages)
        return -ENOMEM;

    for (i = 0; i < num_pages; i++) {
        pages[i] = alloc_page(GFP_KERNEL);
        if (!pages[i]) {
            while (i > 0) {
                i--;
                __free_page(pages[i]);
            }
            kfree(pages);
            return -ENOMEM;
        }
    }

    ret = nfs_call_get_acl(inode, pages, num_pages);
    if (ret < 0) {
        for (i = 0; i < num_pages; i++)
            __free_page(pages[i]);
        kfree(pages);
        return ret;
    }

    for (i = 0; i < num_pages; i++) {
        char *page_data = kmap(pages[i]);
        size_t copy_size = min(buflen, (size_t)PAGE_SIZE);
        if (copy_size > 0)
            memcpy(buf, page_data, copy_size);
        buf += copy_size;
        buflen -= copy_size;
        kunmap(pages[i]);
        __free_page(pages[i]);
    }

    kfree(pages);
    return ret;
}

