ssize_t get_acl_uncached(struct inode *inode, void *buf, size_t buflen) {
    struct page **pages;
    size_t num_pages = (buflen + PAGE_SIZE - 1) / PAGE_SIZE;
    ssize_t ret;
    int i;

    pages = kmalloc_array(num_pages, sizeof(struct page *), GFP_KERNEL);
    if (!pages)
        return -ENOMEM;

    for (i = 0; i < num_pages; i++) {
        pages[i] = alloc_page(GFP_KERNEL);
        if (!pages[i]) {
            while (i--)
                __free_page(pages[i]);
            kfree(pages);
            return -ENOMEM;
        }
    }

    // Prepare and send the synchronous NFS call
    ret = nfs_call_getacl(inode, pages, num_pages);
    if (ret < 0) {
        // Free pages if the call fails
        for (i = 0; i < num_pages; i++)
            __free_page(pages[i]);
        kfree(pages);
        return ret;
    }

    // Copy ACL data into the provided buffer
    for (i = 0; i < num_pages && buflen > 0; i++) {
        size_t len = min(PAGE_SIZE, buflen);
        char *page_addr = kmap(pages[i]);

        memcpy(buf, page_addr, len);
        buf = (void *)((char *)buf + len);
        buflen -= len;
        kunmap(pages[i]);
    }

    // Free allocated pages
    for (i = 0; i < num_pages; i++)
        __free_page(pages[i]);
    kfree(pages);

    return (ssize_t)(len - buflen);
}

ssize_t get_acl_uncached(struct inode *inode, void *buf, size_t buflen) {
    struct page **pages;
    ssize_t ret = 0;
    size_t num_pages = (buflen + PAGE_SIZE - 1) / PAGE_SIZE;

    pages = kmalloc_array(num_pages, sizeof(struct page *), GFP_KERNEL);
    if (!pages)
        return -ENOMEM;

    for (size_t i = 0; i < num_pages; i++) {
        pages[i] = alloc_page(GFP_KERNEL);
        if (!pages[i]) {
            while (i--)
                __free_page(pages[i]);
            kfree(pages);
            return -ENOMEM;
        }
    }

    ret = nfs_call_getacl(inode, pages, buflen);
    if (ret < 0) {
        while (num_pages--)
            __free_page(pages[num_pages]);
        kfree(pages);
        return ret;
    }

    for (size_t i = 0; i < num_pages; i++) {
        void *page_data = kmap(pages[i]);
        size_t copy_len = min(PAGE_SIZE, (size_t)(ret - i * PAGE_SIZE));
        memcpy(buf + i * PAGE_SIZE, page_data, copy_len);
        kunmap(pages[i]);
        __free_page(pages[i]);
    }

    kfree(pages);
    return ret;
}

ssize_t get_acl_uncached(struct inode *inode, void *buf, size_t buflen) {
    struct page **pages = NULL;
    size_t npages = (buflen + PAGE_SIZE - 1) / PAGE_SIZE;
    ssize_t ret = 0;

    pages = kmalloc_array(npages, sizeof(struct page *), GFP_KERNEL);
    if (!pages)
        return -ENOMEM;

    for (size_t i = 0; i < npages; i++) {
        pages[i] = alloc_page(GFP_KERNEL);
        if (!pages[i]) {
            while (i--)
                __free_page(pages[i]);
            kfree(pages);
            return -ENOMEM;
        }
    }

    struct nfs4_getacl args = {
        .ino = inode->i_ino,
        .pages = pages,
        .nr_pages = npages,
    };

    ret = nfs4_call_sync(inode->i_sb, &args, NULL, 0, 0);
    if (ret < 0)
        goto out;

    for (size_t i = 0; i < npages; i++) {
        void *page_data = kmap(pages[i]);
        size_t copy_len = min(PAGE_SIZE, (size_t)ret);

        if (buf) {
            memcpy(buf, page_data, copy_len);
            buf += copy_len;
        }

        kunmap(pages[i]);
        ret -= copy_len;
        if (ret <= 0)
            break;
    }

    ret = buflen - (size_t)ret;
out:
    for (size_t i = 0; i < npages; i++)
        __free_page(pages[i]);
    kfree(pages);
    return ret;
}
